__doc__ = """NumPy-backed implementation of the generic resizable buffer."""


import numpy as np
from .buffer import Buffer


class NumPyBuffer(Buffer):
    """A buffer class that supports numpy"""

    DTYPE_MAP = {
        "int": np.int32,
        "int32": np.int32,
        "int64": np.int64,
        "float": np.float64,
        "float32": np.float32,
        "float64": np.float64,
    }

    def create_new_buffer(self, size, dtype):
        return np.zeros(size, dtype=self.map_dtype(dtype))
